namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Bruschetta", Category = "appetizers", Ingredients = "Baguette\nTomatoes\nBasil\nGarlic\nOlive oil", Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with minced garlic, basil, and olive oil.\n3. Spoon mixture onto toasted bread and serve.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers", Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParsley\nBreadcrumbs", Steps = "1. Remove stems from mushrooms.\n2. Mix cream cheese, garlic, parsley, and breadcrumbs.\n3. Fill mushroom caps and bake at 375°F for 20 minutes.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses", Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper", Steps = "1. Cook spaghetti al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with Parmesan.\n4. Toss hot pasta with pancetta, then stir in egg mixture off heat.\n5. Season with black pepper.", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 4, Title = "Chicken Stir-Fry", Category = "main-courses", Ingredients = "Chicken breast\nBell peppers\nSoy sauce\nGinger\nRice", Steps = "1. Slice chicken and vegetables.\n2. Stir-fry chicken in hot oil until cooked.\n3. Add vegetables and ginger, cook 3 minutes.\n4. Add soy sauce and serve over rice.", AverageRating = 4.3, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold in chocolate mixture and flour.\n4. Pour into ramekins and bake at 425°F for 12 minutes.\n5. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Tiramisu", Category = "desserts", Ingredients = "Ladyfingers\nMascarpone\nEspresso\nCocoa powder\nEggs\nSugar", Steps = "1. Whisk egg yolks with sugar, fold in mascarpone.\n2. Dip ladyfingers in espresso.\n3. Layer mascarpone mixture and ladyfingers.\n4. Refrigerate 4 hours.\n5. Dust with cocoa powder before serving.", AverageRating = 4.7, RatingCount = 20 },
    };

    private int _nextId = 7;

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public Dictionary<string, string> GetCategories()
    {
        return new Dictionary<string, string>
        {
            ["appetizers"] = "Appetizers",
            ["main-courses"] = "Main Courses",
            ["desserts"] = "Desserts"
        };
    }
}

