@page "/recipes"
@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Recipes - @(_categoryName ?? "All Categories")</PageTitle>

<h1>@(_categoryName ?? "Browse Recipes")</h1>

@if (string.IsNullOrEmpty(Category))
{
    <p>Select a category to browse recipes:</p>
    <ul>
        @foreach (var cat in RecipeService.GetCategories())
        {
            <li><a href="recipes/@cat.Key">@cat.Value</a></li>
        }
    </ul>
}
else if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
    <a href="recipes">← Back to categories</a>
}
else
{
    <a href="recipes">← Back to categories</a>
    <div class="row mt-3">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private List<RecipeShare.Models.Recipe> _recipes = new();
    private string? _categoryName;

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(Category))
        {
            _recipes = RecipeService.GetByCategory(Category);
            var categories = RecipeService.GetCategories();
            _categoryName = categories.GetValueOrDefault(Category, Category);
        }
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes">← Browse recipes</a>
}
else
{
    <PageTitle>@_recipe.Title - RecipeShare</PageTitle>

    <a href="recipes/@_recipe.Category">← Back to category</a>

    <h1 class="mt-3">@_recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="@_recipe.Id" CurrentRating="@_recipe.AverageRating" RatingCount="@_recipe.RatingCount" />
    </div>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
    {
        <p>@step</p>
    }
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" style="cursor:pointer; font-size:1.5rem;" @onclick="() => Rate(star)">
                @(star <= Math.Round(CurrentRating) ? "★" : "☆")
            </span>
        }
    </span>
    <span class="text-muted">@CurrentRating / 5 (@RatingCount ratings)</span>
    @if (_submitted)
    {
        <span class="text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private bool _submitted;

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_title" has been added.
        <a href="recipes/@_category">View it in the category →</a>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_steps" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;

    private bool IsValid => !string.IsNullOrWhiteSpace(_title)
        && !string.IsNullOrWhiteSpace(_category)
        && !string.IsNullOrWhiteSpace(_ingredients)
        && !string.IsNullOrWhiteSpace(_steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        RecipeService.AddRecipe(new RecipeShare.Models.Recipe
        {
            Title = _title,
            Category = _category,
            Ingredients = _ingredients,
            Steps = _steps
        });

        _submitted = true;
    }

    private void Reset()
    {
        _title = string.Empty;
        _category = string.Empty;
        _ingredients = string.Empty;
        _steps = string.Empty;
        _submitted = false;
    }
}

