toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_title" has been added.
        <a href="recipes/@_category">View it in the category →</a>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_steps" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;

    private bool IsValid => !string.IsNullOrWhiteSpace(_title)
        && !string.IsNullOrWhiteSpace(_category)
        && !string.IsNullOrWhiteSpace(_ingredients)
        && !string.IsNullOrWhiteSpace(_steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        RecipeService.AddRecipe(new RecipeShare.Models.Recipe
        {
            Title = _title,
            Category = _category,
            Ingredients = _ingredients,
            Steps = _steps
        });

        _submitted = true;
    }

    private void Reset()
    {
        _title = string.Empty;
        _category = string.Empty;
        _ingredients = string.Empty;
        _steps = string.Empty;
        _submitted = false;
    }
}

